// Extract Complete Error Context
const items = $input.all();
const error = items[0];

const errorContext = {
  // Error details
  message: error.json.message || 'Unknown error',
  stack: error.json.stack || '',
  code: error.json.code || '',

  // Workflow context
  workflowId: $workflow.id,
  workflowName: $workflow.name,
  executionId: $execution.id,
  mode: $execution.mode,

  // Node context
  nodeName: error.json.node?.name || 'Unknown',
  nodeType: error.json.node?.type || 'Unknown',

  // Timing
  timestamp: new Date().toISOString(),
  executionTime: $execution.endedAt ? ($execution.endedAt - $execution.startedAt) : 0,

  // Input data (truncated to 1000 chars)
  inputData: JSON.stringify(error.json.input || {}).substring(0, 1000),

  // Environment
  environment: process.env.NODE_ENV || process.env.DEPLOYMENT_ENVIRONMENT || 'unknown',

  // Error classification will be added in next node
  severity: 'unknown'
};

return [{ json: errorContext }];

// Classify Error Severity
const error = $json;

let severity = 'info';
let color = '#36a64f'; // green
let emoji = 'ℹ️';

// Critical: Production errors affecting users or core functionality
if (error.environment === 'production') {
  if (
    error.code === 'ECONNREFUSED' ||
    error.message.toLowerCase().includes('database') ||
    error.message.toLowerCase().includes('payment') ||
    error.message.toLowerCase().includes('authentication') ||
    error.message.toLowerCase().includes('critical')
  ) {
    severity = 'critical';
    color = '#ff0000'; // red
    emoji = '🚨';
  }
  // Warning: Production errors but non-critical
  else if (
    error.code === 'ETIMEDOUT' ||
    error.message.toLowerCase().includes('timeout') ||
    error.message.toLowerCase().includes('retry')
  ) {
    severity = 'warning';
    color = '#ffa500'; // orange
    emoji = '⚠️';
  }
}

// Warning: Staging errors
if (error.environment === 'staging') {
  severity = 'warning';
  color = '#ffff00'; // yellow
  emoji = '🔶';
}

// Info: Development errors
if (error.environment === 'development' || error.environment === 'dev') {
  severity = 'info';
  color = '#36a64f'; // green
  emoji = 'ℹ️';
}

error.severity = severity;
error.color = color;
error.emoji = emoji;

return [{ json: error }];

// Format Slack Message for Critical Errors
const error = $json;

const slackMessage = {
  channel: process.env.SLACK_ALERTS_CHANNEL || '#alerts',
  text: `${error.emoji} CRITICAL ERROR in ${error.workflowName}`,
  blocks: [
    {
      type: "header",
      text: {
        type: "plain_text",
        text: `${error.emoji} CRITICAL Error in ${error.workflowName}`
      }
    },
    {
      type: "section",
      fields: [
        {
          type: "mrkdwn",
          text: `*Environment:*\n${error.environment}`
        },
        {
          type: "mrkdwn",
          text: `*Node:*\n${error.nodeName}`
        },
        {
          type: "mrkdwn",
          text: `*Time:*\n${error.timestamp}`
        },
        {
          type: "mrkdwn",
          text: `*Execution ID:*\n\`${error.executionId}\``
        }
      ]
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: `*Error Message:*\n\`\`\`${error.message.substring(0, 500)}\`\`\``
      }
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: `*Input Data:*\n\`\`\`${error.inputData}\`\`\``
      }
    },
    {
      type: "context",
      elements: [
        {
          type: "mrkdwn",
          text: `Workflow ID: \`${error.workflowId}\` | Execution Time: ${error.executionTime}ms`
        }
      ]
    },
    {
      type: "actions",
      elements: [
        {
          type: "button",
          text: {
            type: "plain_text",
            text: "View Execution"
          },
          url: `${process.env.N8N_EDITOR_BASE_URL || 'http://localhost:5678'}/execution/${error.executionId}`,
          style: "danger"
        }
      ]
    }
  ],
  attachments: [
    {
      color: error.color,
      fields: [
        {
          title: "Node Type",
          value: error.nodeType,
          short: true
        },
        {
          title: "Error Code",
          value: error.code || 'N/A',
          short: true
        }
      ]
    }
  ]
};

return [{ json: slackMessage }];

// Format Slack Message for Warnings
const error = $json;

const slackMessage = {
  channel: process.env.SLACK_WARNINGS_CHANNEL || '#warnings',
  text: `${error.emoji} Warning in ${error.workflowName}`,
  blocks: [
    {
      type: "header",
      text: {
        type: "plain_text",
        text: `${error.emoji} Warning in ${error.workflowName}`
      }
    },
    {
      type: "section",
      fields: [
        {
          type: "mrkdwn",
          text: `*Environment:*\n${error.environment}`
        },
        {
          type: "mrkdwn",
          text: `*Node:*\n${error.nodeName}`
        },
        {
          type: "mrkdwn",
          text: `*Time:*\n${error.timestamp}`
        }
      ]
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: `*Error Message:*\n\`\`\`${error.message.substring(0, 300)}\`\`\``
      }
    },
    {
      type: "actions",
      elements: [
        {
          type: "button",
          text: {
            type: "plain_text",
            text: "View Execution"
          },
          url: `${process.env.N8N_EDITOR_BASE_URL || 'http://localhost:5678'}/execution/${error.executionId}`
        }
      ]
    }
  ]
};

return [{ json: slackMessage }];

// Log Info Errors (development/staging)
const error = $json;

console.log(`[INFO ERROR] ${error.workflowName} - ${error.nodeName}: ${error.message}`);

return [{ json: error }];

// Update Error Metrics
const error = $json;

// Increment error counter (this would typically be sent to Prometheus)
const metrics = {
  metric: 'n8n_errors_total',
  labels: {
    workflow_id: error.workflowId,
    workflow_name: error.workflowName,
    severity: error.severity,
    environment: error.environment,
    node_type: error.nodeType
  },
  value: 1,
  timestamp: Date.now()
};

console.log(`[METRICS] Error logged: ${JSON.stringify(metrics)}`);

return [{ json: { ...error, metrics } }];
